def _extension_binary(arch: str) -> bytes:
    raw = lzma.decompress(base64.b64decode("".join(_LZMA_B64[arch].split())))
    got = hashlib.sha256(raw).hexdigest()
    assert got == _SHA256[arch], (
        f"embedded {arch} extension binary is sha256 {got!r}, pinned {_SHA256[arch]!r} — the "
        f"check would run bytes it never recorded"
    )
    return raw


# One handler per language family. Each is feature-neutral across every supported version of its
# runtime (no version-pinned syntax), reads back the extension's own /tmp log and reports the
# interpreter's own view of its runtime identity so the check can relate it to the Runtime the
# function was created with, never to a literal version string of its own.
PYTHON_HANDLER = '''\
import json
import os
import time
import uuid

ENV_ID = str(uuid.uuid4())
INVOKE_COUNT = 0
EXT_LOG = "/tmp/sim2real-ext.log"


def _read(request_id, budget_s=5.0):
    deadline = time.time() + budget_s
    while True:
        recs = []
        if os.path.exists(EXT_LOG):
            with open(EXT_LOG) as fh:
                for line in fh:
                    line = line.strip()
                    if line:
                        recs.append(json.loads(line))
        if any(r.get("kind") == "invoke" and r["event"].get("requestId") == request_id
               for r in recs):
            return recs
        if time.time() >= deadline:
            return recs
        time.sleep(0.1)


def handler(event, context):
    global INVOKE_COUNT
    INVOKE_COUNT += 1
    if event.get("hang"):
        time.sleep(600)
    recs = _read(context.aws_request_id)
    return {
        "env_id": ENV_ID,
        "invoke_count": INVOKE_COUNT,
        "request_id": context.aws_request_id,
        "exec_env": os.environ.get("AWS_EXECUTION_ENV", ""),
        "ext_records": recs,
    }
'''

NODEJS_HANDLER = '''\
const fs = require("fs");

const envId = require("crypto").randomUUID();
let invokeCount = 0;
const EXT_LOG = "/tmp/sim2real-ext.log";

function sleepMs(ms) {
  const sab = new SharedArrayBuffer(4);
  Atomics.wait(new Int32Array(sab), 0, 0, ms);
}

function readRecords(requestId, budgetMs) {
  const deadline = Date.now() + budgetMs;
  for (;;) {
    let recs = [];
    if (fs.existsSync(EXT_LOG)) {
      const lines = fs.readFileSync(EXT_LOG, "utf8").split("\\n");
      for (const line of lines) {
        if (line.trim()) recs.push(JSON.parse(line));
      }
    }
    if (recs.some((r) => r.kind === "invoke" && r.event && r.event.requestId === requestId)) {
      return recs;
    }
    if (Date.now() >= deadline) return recs;
    sleepMs(100);
  }
}

exports.handler = async (event, context) => {
  invokeCount += 1;
  if (event && event.hang) {
    await new Promise((resolve) => setTimeout(resolve, 600000));
  }
  const recs = readRecords(context.awsRequestId, 5000);
  return {
    env_id: envId,
    invoke_count: invokeCount,
    request_id: context.awsRequestId,
    exec_env: process.env.AWS_EXECUTION_ENV || "",
    ext_records: recs,
  };
};
'''

RUBY_HANDLER = '''\
require "json"
require "securerandom"

ENV_ID = SecureRandom.uuid
$invoke_count = 0
EXT_LOG = "/tmp/sim2real-ext.log"

def read_records(request_id, budget_s = 5.0)
  deadline = Time.now.to_f + budget_s
  loop do
    recs = []
    if File.exist?(EXT_LOG)
      File.readlines(EXT_LOG).each do |line|
        line = line.strip
        recs << JSON.parse(line) unless line.empty?
      end
    end
    found = recs.any? { |r| r["kind"] == "invoke" && r.dig("event", "requestId") == request_id }
    return recs if found || Time.now.to_f >= deadline
    sleep 0.1
  end
end

def handler(event:, context:)
  $invoke_count += 1
  sleep 600 if event["hang"]
  recs = read_records(context.aws_request_id)
  {
    env_id: ENV_ID,
    invoke_count: $invoke_count,
    request_id: context.aws_request_id,
    exec_env: ENV["AWS_EXECUTION_ENV"] || "",
    ext_records: recs,
  }
end
'''

# (Runtime, Architecture, handler source, handler filename, Lambda Handler string): the same
# extension layer attaches to all three; only the handler language and the architecture differ.
_FAMILIES = [
    ("python3.13", "arm64", PYTHON_HANDLER, "index.py", "index.handler"),
    ("nodejs22.x", "x86_64", NODEJS_HANDLER, "index.js", "index.handler"),
    ("ruby3.4", "arm64", RUBY_HANDLER, "function.rb", "function.handler"),
]


def _code_zip(filename: str, src: str) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(filename, src)
    return buf.getvalue()


def _layer_zip(arch: str) -> bytes:
    """``extensions/<name>`` at mode 0o755; a non-executable entry is silently skipped by Lambda."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        info = zipfile.ZipInfo(f"extensions/{EXT_NAME}")
        info.external_attr = 0o755 << 16
        zf.writestr(info, _extension_binary(arch))
    return buf.getvalue()


def _teardown(undo, *not_found: str):
    def run_undo() -> None:
        try:
            undo()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in not_found:
                return
            raise

    return run_undo


def _reap_log_group(logs, name: str, *, reads: int = 3, interval_s: float = 5.0,
                    budget_s: float = 180.0) -> None:
    """Delete log group ``name`` until ``reads`` consecutive reads find it absent.

    A log stream buffered by an invocation that already returned can flush after
    DeleteFunction and recreate the group, so one delete is a round, not a teardown.
    """
    deadline = time.monotonic() + budget_s
    absent = 0
    while absent < reads:
        groups = logs.describe_log_groups(logGroupNamePrefix=name)["logGroups"]
        if any(g["logGroupName"] == name for g in groups):
            absent = 0
            try:
                logs.delete_log_group(logGroupName=name)
            except ClientError as exc:
                if exc.response["Error"]["Code"] != "ResourceNotFoundException":
                    raise
        else:
            absent += 1
        if absent < reads:
            if time.monotonic() > deadline:
                raise AssertionError(
                    f"log group {name!r} still present after {budget_s}s of deletes"
                )
            time.sleep(interval_s)


def _execution_role(ctx) -> str:
    iam = ctx.client("iam")
    name = ctx.unique_name("sim2real-behav-role-")
    trust = {"Version": "2012-10-17", "Statement": [{
        "Effect": "Allow", "Principal": {"Service": "lambda.amazonaws.com"},
        "Action": "sts:AssumeRole"}]}
    arn = iam.create_role(RoleName=name, AssumeRolePolicyDocument=json.dumps(trust),
                          Tags=[{"Key": "sim2real", "Value": CHECK}])["Role"]["Arn"]
    ctx.on_cleanup(_teardown(lambda: iam.delete_role(RoleName=name), "NoSuchEntity"))
    partition = ctx.client("sts").get_caller_identity()["Arn"].split(":")[1]
    policy_arn = f"arn:{partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
    iam.attach_role_policy(RoleName=name, PolicyArn=policy_arn)
    ctx.on_cleanup(_teardown(
        lambda: iam.detach_role_policy(RoleName=name, PolicyArn=policy_arn), "NoSuchEntity"))
    return arn


def _create_function_retrying(lam, **kwargs):
    deadline = time.monotonic() + 90
    while True:
        try:
            return lam.create_function(**kwargs)
        except ClientError as e:
            err = e.response.get("Error", {})
            if (err.get("Code") == "InvalidParameterValueException"
                    and "cannot be assumed by Lambda" in err.get("Message", "")
                    and time.monotonic() < deadline):
                time.sleep(3)
                continue
            raise


def _wait_active(lam, fn, timeout_s=180) -> dict:
    deadline = time.monotonic() + timeout_s
    last = None
    while time.monotonic() < deadline:
        last = lam.get_function_configuration(FunctionName=fn)
        if last["State"] == "Failed":
            raise AssertionError(f"{fn} entered Failed: {last.get('StateReason')!r}")
        if last["State"] == "Active" and last.get("LastUpdateStatus") in (None, "Successful"):
            return last
        time.sleep(1.0)
    raise AssertionError(f"{fn} never became Active in {timeout_s}s; last={last!r}")


def _invoke(lam, fn, payload: dict) -> dict:
    resp = lam.invoke(FunctionName=fn, InvocationType="RequestResponse",
                      Payload=json.dumps(payload).encode())
    raw = resp["Payload"].read()
    out = {
        "function_error": resp.get("FunctionError"),
        "raw": raw,
        "request_id": resp["ResponseMetadata"]["RequestId"],
    }
    if not out["function_error"]:
        assert raw, f"{fn} returned an empty payload: {resp!r}"
        out["body"] = json.loads(raw)
    return out


def _records(body: dict, kind: str) -> list:
    return [r for r in body["ext_records"] if r["kind"] == kind]


def _budget_s(ctx, cap_s):
    """A poll's timeout: cap_s, bounded by the check's remaining time less 5 s so the poll fails
    with its own message."""
    left = ctx.time_left()
    return cap_s if left is None else max(1.0, min(cap_s, left - 5.0))


def _budget_spent(ctx):
    """True when the check's remaining time, not the wait's own deadline, ended a capped wait."""
    left = ctx.time_left()
    return left is not None and left <= 6.0


def _invoke_window(logs, group: str, request_id: str):
    """The log lines of invoke ``request_id``, START through REPORT, from CloudWatch Logs; None
    until both lines are delivered."""
    kw: dict = {"logGroupName": group, "filterPattern": f'"{request_id}"'}
    streams = set()
    try:
        while True:
            page = logs.filter_log_events(**kw)
            streams |= {e["logStreamName"] for e in page.get("events", [])}
            if not page.get("nextToken"):
                break
            kw["nextToken"] = page["nextToken"]
        for stream in sorted(streams):
            events, token = [], None
            while True:
                skw = {"logGroupName": group, "logStreamName": stream, "startFromHead": True}
                if token:
                    skw["nextToken"] = token
                page = logs.get_log_events(**skw)
                events += page.get("events", [])
                if not page.get("events") or page.get("nextForwardToken") == token:
                    break
                token = page.get("nextForwardToken")
            lines = [e["message"] for e in events]
            start = next((i for i, m in enumerate(lines) if m.startswith(f"START RequestId: {request_id}")), None)
            end = next((i for i, m in enumerate(lines) if m.startswith(f"REPORT RequestId: {request_id}")), None)
            if start is not None and end is not None and start < end:
                return lines[start:end + 1]
    except ClientError as exc:
        if exc.response["Error"]["Code"] != "ResourceNotFoundException":
            raise
    return None


def _ext_shutdown_records(ctx, logs, group: str, request_id: str) -> list:
    """The extension's SHUTDOWN records logged within invoke ``request_id`` (CloudWatch Logs)."""
    deadline = time.monotonic() + _budget_s(ctx, 180)
    while True:
        window = _invoke_window(logs, group, request_id)
        if window is not None:
            break
        if time.monotonic() > deadline:
            if _budget_spent(ctx):
                raise TimeoutError(f"START..REPORT of {request_id} in {group}: the run budget ended first; not graded")
            raise AssertionError(f"START..REPORT of invoke {request_id} never reached {group}")
        time.sleep(2)
    out = []
    for line in window:
        marker = "EXT_REC "
        idx = line.find(marker)
        if idx < 0:
            continue
        rec = json.loads(line[idx + len(marker):])
        if rec["kind"] == "EXT_SHUTDOWN":
            out.append(rec)
    return out


@tags("axis:happy-path", "cap:c3", "concern:data-plane", "dp:api", "plane:data")
def run(ctx) -> None:
    """The same external-extension layer registers, receives INVOKE and SHUTDOWN identically when
    attached to a Python, a Node.js and a Ruby function on mixed architectures, and each
    function's own execution environment names the Runtime it was created with.

    Reference: https://docs.aws.amazon.com/lambda/latest/dg/runtimes-extensions-api.html
    Reference: https://docs.aws.amazon.com/lambda/latest/dg/configuration-envvars.html
    """
    lam = ctx.client("lambda")
    role = _execution_role(ctx)

    layer_arns: dict = {}
    for arch in ("x86_64", "arm64"):
        layer_name = ctx.unique_name(f"sim2real-behav-extlayer-{arch}-")
        layer = lam.publish_layer_version(
            LayerName=layer_name, Description="sim2real cross-runtime extension",
            Content={"ZipFile": _layer_zip(arch)}, CompatibleArchitectures=[arch])
        ctx.on_cleanup(_teardown(
            lambda n=layer_name, v=layer["Version"]:
            lam.delete_layer_version(LayerName=n, VersionNumber=v), "ResourceNotFoundException"))
        layer_arns[arch] = layer["LayerVersionArn"]

    logs = ctx.client("logs")
    results = []
    for runtime, arch, handler_src, filename, handler_str in _FAMILIES:
        fn = ctx.unique_name("sim2real-behav-extfam-")
        # Registered before create_function, so LIFO reaps the log group AFTER the function's
        # own delete below: DeleteFunction never removes /aws/lambda/<fn> itself.
        ctx.on_cleanup(lambda n=fn: _reap_log_group(logs, f"/aws/lambda/{n}"))
        _create_function_retrying(
            lam, FunctionName=fn, Runtime=runtime, Handler=handler_str, Role=role,
            Code={"ZipFile": _code_zip(filename, handler_src)},
            Architectures=[arch], MemorySize=512, Timeout=FN_TIMEOUT_S,
            Layers=[layer_arns[arch]], Tags={"sim2real": CHECK})
        ctx.on_cleanup(_teardown(lambda n=fn: lam.delete_function(FunctionName=n),
                                 "ResourceNotFoundException"))
        conf = _wait_active(lam, fn)
        assert conf["Runtime"] == runtime and conf["Architectures"] == [arch], (
            f"{fn} configuration drifted from what was requested: Runtime={conf['Runtime']!r} "
            f"Architectures={conf['Architectures']!r}, wanted {runtime!r}/{arch!r}")

        cold = _invoke(lam, fn, {})
        assert not cold["function_error"], (
            f"{runtime}/{arch}: the extension must not break the invocation: "
            f"FunctionError={cold['function_error']!r} {cold['raw'][:400]!r}")
        warm = _invoke(lam, fn, {})
        assert not warm["function_error"], (
            f"{runtime}/{arch}: warm invoke failed: FunctionError={warm['function_error']!r} "
            f"{warm['raw'][:400]!r}")

        for body, tag in ((cold["body"], "cold"), (warm["body"], "warm")):
            assert runtime in body["exec_env"], (
                f"{runtime}/{arch} {tag}: AWS_EXECUTION_ENV {body['exec_env']!r} does not name "
                f"the Runtime {runtime!r} the function was created with")
            regs = _records(body, "register")
            assert regs, f"{runtime}/{arch} {tag}: no registration record: {body['ext_records']!r}"
            ident = regs[-1]["identifier"]
            assert ident and str(uuid.UUID(ident)) == ident, (
                f"{runtime}/{arch} {tag}: Lambda-Extension-Identifier {ident!r} is not a UUID")
            invokes = [r for r in _records(body, "invoke") if r["identifier"] == ident]
            assert invokes and invokes[-1]["event"]["requestId"] == body["request_id"], (
                f"{runtime}/{arch} {tag}: the registered extension never received an INVOKE "
                f"carrying this invocation's own request id {body['request_id']!r}: "
                f"{invokes!r}")
            event = invokes[-1]["event"]
            assert event["tracing"]["type"] == "X-Amzn-Trace-Id", (
                f"{runtime}/{arch} {tag}: tracing.type must be 'X-Amzn-Trace-Id', got "
                f"{event.get('tracing')!r}")

        dying = _invoke(lam, fn, {"hang": True})
        assert dying["function_error"] == "Unhandled", (
            f"{runtime}/{arch}: an invocation that outruns Timeout={FN_TIMEOUT_S}s must return "
            f"FunctionError, got {dying['function_error']!r}: {dying['raw'][:400]!r}")
        shutdowns = _ext_shutdown_records(ctx, logs, f"/aws/lambda/{fn}", dying["request_id"])
        assert len(shutdowns) == 1, (
            f"{runtime}/{arch}: the dying environment must deliver exactly one SHUTDOWN event "
            f"within the timed-out invoke's CloudWatch log lines, got {shutdowns!r}")
        reason = shutdowns[0]["event"]["shutdownReason"]
        results.append({"runtime": runtime, "arch": arch, "shutdown_reason": reason})

    # The three families must agree on the one thing the layer, not the language, controls: the
    # documented reason Lambda hands the extension for a forced-timeout shutdown.
    reasons = {r["shutdown_reason"] for r in results}
    assert reasons == {"timeout"}, (
        f"the three runtime families disagree on the SHUTDOWN reason for an identical forced "
        f"timeout: {results!r}")


if __name__ == "__main__":
    from fidelity_tests_runner import main
    main(run)
